import os
from typing import List

def check_secret_label_safety(secret_name: str, unsafe_keywords: List[str] = None, vault_url: str = None) -> dict:
    client = AzureKeyVaultSecurityClient(vault_url)
    secret_properties = client.client.get_secret_properties(secret_name)

    if unsafe_keywords is None:
        unsafe_keywords = ["password", "credential", "token", "key", "secret_value"]

    unsafe_labels = []
    if secret_properties.tags:
        for key, value in secret_properties.tags.items():
            for keyword in unsafe_keywords:
                if keyword in key.lower() or keyword in value.lower():
                    unsafe_labels.append(f"Tag '{key}': '{value}' contains unsafe keyword '{keyword}'")

    # Azure Key Vault secret properties don't have a direct 'notes' field.
    # We'll simulate checking a 'description' tag or similar if it were present.
    # For this example, we focus on tags.

    return {
        "secret_id": secret_name,
        "has_unsafe_labels": len(unsafe_labels) > 0,
        "unsafe_findings": unsafe_labels
    }

from security_models import AuditNote
import os
from openai import AzureOpenAI
from typing import List

def embed_audit_notes(audit_notes: List[AuditNote], azure_openai_endpoint: str = None, azure_openai_key: str = None, embedding_model: str = "text-embedding-ada-002") -> List[dict]:
    if azure_openai_endpoint is None:
        azure_openai_endpoint = os.environ.get("AZURE_OPENAI_ENDPOINT")
    if azure_openai_key is None:
        azure_openai_key = os.environ.get("AZURE_OPENAI_API_KEY")

    if not azure_openai_endpoint or not azure_openai_key:
        raise ValueError("Azure OpenAI endpoint and API key must be provided or set in environment variables.")

    client = AzureOpenAI(
        azure_endpoint=azure_openai_endpoint,
        api_key=azure_openai_key,
        api_version="2023-05-15"
    )

    embeddings_results = []
    for note in audit_notes:
        response = client.embeddings.create(input=note.text, model=embedding_model)
        embeddings_results.append({
            "audit_note_id": note.id,
            "text": note.text,
            "embedding": response.data[0].embedding
        })
    return embeddings_results

import os
import requests
from typing import List
from security_models import TranslatedText

def translate_runbook_notes(text_to_translate: str, target_language: str, azure_translator_endpoint: str = None, azure_translator_key: str = None, azure_translator_region: str = None) -> TranslatedText:
    if azure_translator_endpoint is None:
        azure_translator_endpoint = os.environ.get("AZURE_TRANSLATOR_ENDPOINT")
    if azure_translator_key is None:
        azure_translator_key = os.environ.get("AZURE_TRANSLATOR_API_KEY")
    if azure_translator_region is None:
        azure_translator_region = os.environ.get("AZURE_TRANSLATOR_REGION")

    if not azure_translator_endpoint or not azure_translator_key or not azure_translator_region:
        raise ValueError("Azure Translator endpoint, API key, and region must be provided or set in environment variables.")

    path = '/translate'
    constructed_url = azure_translator_endpoint + path

    headers = {
        'Ocp-Apim-Subscription-Key': azure_translator_key,
        'Ocp-Apim-Subscription-Region': azure_translator_region,
        'Content-type': 'application/json',
        'X-ClientTraceId': str(os.urandom(16))
    }

    params = {
        'api-version': '3.0',
        'to': target_language
    }

    body = [{'text': text_to_translate}]

    request = requests.post(constructed_url, params=params, headers=headers, json=body)
    response = request.json()

    translated_text = response[0]['translations'][0]['text']

    return TranslatedText(
        original_text=text_to_translate,
        translated_text=translated_text,
        target_language=target_language
    )
